/// <summary>
/// PricingAttribute of table <c>RetailSalesTable</c> field DiscountCodes.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
class UPSPricingAttributeRetailSalesTableDiscountCodes extends UPSPricingAttributeRetailSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailSalesTable, DiscountCodes);
}

public Set getAllowedValues()
{
    RetailSalesTable    retailSalesTable;
    var                 ret = new Set(Types::Container);

    while select DiscountCodes from retailSalesTable
        group by DiscountCodes
    {
        ret.add(retailSalesTable.ChannelReferenceId);
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailSalesTable, DiscountCodes));
    qbr.value(queryValue(_value));
}
